import type { RecoveryCode } from '../../../shared/domain/RecoveryCode.ts';
import type { ApprovalPreview, Evidence } from '../api/IdentityGateway.ts';

/** The purpose of the flow that shows a new recovery code. */
export type IssuePurpose = 'first' | 'regen' | 'recover';

/** A new recovery code generated by the SERVER and how to commit it (the code takes effect only when `commit` succeeds, QĐ-6). */
export interface IssueSession {
  readonly code: RecoveryCode;
  /** Commits the code as soon as the user types it again correctly; throws `ApiError` if the server refuses (expired, the code changed...). */
  readonly commit: () => Promise<void>;
}

/** Describes a flow that issues a new recovery code (get the code from the server -> show the code -> type 2 groups again -> a last review). */
export interface IssueSpec {
  readonly purpose: IssuePurpose;
  /** Asks the server for a new code (called exactly ONCE when the sheet opens); throws `ApiError` if it could not be requested. */
  readonly open: () => Promise<IssueSession>;
  /** Called when the user taps Done at the last step. */
  readonly onDone: () => void;
  /** First-time flow only: 'Later' (saves the trip without a code yet). */
  readonly onSkip?: () => void;
  /** The sheet could not be opened (network error, refused): tells the user and then closes. */
  readonly onOpenFailed?: (error: unknown) => void;
  /** The server says the attempt expired when confirming: replaces the generic error message (for example recovery leads the user back to the code-entry step). */
  readonly onExpired?: () => void;
}

/** The result of one re-authentication: done (the next flow has opened), or the evidence is not enough (wrong code, not approved yet). */
export type ReauthAttempt = (evidence: Evidence) => Promise<boolean>;

/** The overlay-sheet flows of the identity (one at a time). */
export type Flow =
  | { readonly kind: 'intro'; readonly onSaved: () => unknown; /** There is an old identity with no way to recover (branch B): creating a new one would lose the old trips. */ readonly replacing?: boolean }
  | { readonly kind: 'issue'; readonly issue: IssueSpec }
  | { readonly kind: 'reauth'; readonly title: string; readonly why: string; readonly attempt: ReauthAttempt }
  | { readonly kind: 'revoke'; readonly deviceId: string }
  | { readonly kind: 'pairConfirm'; readonly preview: ApprovalPreview };
